/* Slovenian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Janez": "God is gracious — Hebrew Yohanan", "Marija": "The most beloved feminine name.", "Franc": "free, Frenchman — Germanic", "Ana": "grace — Hebrew Hannah", "Marko": "of Mars, warlike — Latin Marcus", "Eva": "life — Hebrew", "Novak": "The most common Slovenian surname; feminine Novakova or Novak.", "Horvat": "A widespread surname.", "Kovacic": "A classic diminutive surname.", "Krajnc": "A regional surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Janez';
console.log(lookup(q));

